"use server";

import { getCourseById } from "./get-course-by-slug";
import { listModules } from "../module/list-modules";
import { listGroups } from "../group/list-groups";
import { listLessons } from "../lesson/list-lessons";

export interface ModuleWithStructure {
  id: string;
  title: string;
  slug: string;
  courseId: string;
  orderIndex: number;
  groups: GroupWithStructure[];
}

export interface GroupWithStructure {
  id: number;
  title: string;
  moduleId: string;
  orderIndex: number;
  lessons: LessonWithStructure[];
}

export interface LessonWithStructure {
  id: number;
  title: string;
  description: string;
  type: string;
  slug: string;
  url: string | null;
  isFree: boolean;
  video_url: string | null;
  video_duration: string | null;
  video?: { url: string | null; duration: string | null } | null;
  article?: { body: string } | null;
  quiz?: { content: import('../lesson/list-lessons').Challenge[] } | null;
  locked: boolean;
  completed: boolean;
  submoduleId: number;
  order: number;
  createdAt: string;
  updatedAt: string;
  authorId: string;
}

export interface CourseWithStructure {
  course: Awaited<ReturnType<typeof getCourseById>>;
  modules: ModuleWithStructure[];
}

/**
 * Busca um curso completo com sua estrutura hierárquica (módulos, grupos e aulas)
 */
export async function getCourseWithStructure(
  courseId: string
): Promise<CourseWithStructure | null> {
  try {
    // Buscar curso
    const course = await getCourseById(courseId);
    if (!course) {
      return null;
    }

    // Buscar módulos
    const { modules: modulesList } = await listModules(courseId);

    // Para cada módulo, buscar grupos e aulas
    const modulesWithStructure: ModuleWithStructure[] = await Promise.all(
      modulesList.map(async (module) => {
        const { groups: groupsList } = await listGroups(module.id);

        const groupsWithStructure: GroupWithStructure[] = await Promise.all(
          groupsList.map(async (group) => {
            const { lessons: lessonsList } = await listLessons(group.id);

            return {
              id: group.id,
              title: group.title,
              moduleId: group.moduleId,
              orderIndex: (group as any).orderIndex || 0,
              lessons: lessonsList.map((lesson) => ({
                id: parseInt(lesson.id, 10),
                title: lesson.title,
                description: lesson.description,
                type: lesson.type,
                slug: lesson.slug,
                url: lesson.url || null,
                isFree: lesson.isFree,
                video_url: lesson.video?.url ?? lesson.video_url ?? null,
                video_duration: lesson.video?.duration ?? lesson.video_duration ?? null,
                video: lesson.video ?? null,
                article: lesson.article ?? null,
                quiz: lesson.quiz ?? null,
                locked: lesson.locked,
                completed: false,
                submoduleId: lesson.submoduleId,
                order: lesson.order || 0,
                createdAt: lesson.createdAt,
                updatedAt: lesson.updatedAt,
                authorId: lesson.authorId,
              })),
            };
          })
        );

        // Ordenar grupos por orderIndex
        groupsWithStructure.sort((a, b) => a.orderIndex - b.orderIndex);

        // Ordenar aulas dentro de cada grupo por order
        groupsWithStructure.forEach((group) => {
          group.lessons.sort((a, b) => a.order - b.order);
        });

        return {
          id: module.id,
          title: module.title,
          slug: module.slug,
          courseId: module.courseId,
          orderIndex: (module as any).orderIndex || 0,
          groups: groupsWithStructure,
        };
      })
    );

    // Ordenar módulos por orderIndex
    modulesWithStructure.sort((a, b) => a.orderIndex - b.orderIndex);

    return {
      course,
      modules: modulesWithStructure,
    };
  } catch (error) {
    console.error("Erro ao buscar curso com estrutura:", error);
    return null;
  }
}

"use server";

import { buildApiHeaders } from "@/actions/auth";

export interface UpdateRequestData {
  status?: "PENDING" | "APPROVED" | "REJECTED" | "IN_PROGRESS";
  response?: string;
}

export interface UpdateRequestResponse {
  success: boolean;
  message: string;
  request?: any;
}

export async function updateRequest(
  id: string,
  data: UpdateRequestData,
  token: string
): Promise<UpdateRequestResponse> {
  try {
    const response = await fetch(
      `${process.env.NEXT_PUBLIC_API_URL}/requests/${id}`,
      {
        method: "PUT",
        headers: await buildApiHeaders(undefined, token),
        body: JSON.stringify(data),
        cache: "no-store",
      }
    );

    if (!response.ok) {
      const errorData = await response.json().catch(() => ({}));
      return {
        success: false,
        message: errorData.message || "Erro ao atualizar solicitação",
      };
    }

    const result = await response.json();

    return {
      success: true,
      message: "Solicitação atualizada com sucesso",
      request: result.request,
    };
  } catch (error) {
    console.error("Erro ao atualizar solicitação:", error);
    return {
      success: false,
      message: "Erro ao atualizar solicitação. Tente novamente.",
    };
  }
}

"use client";

import { useState, useEffect } from "react";
import { useRouter, useParams } from "next/navigation";
import { MainLayout } from "@/components/layout/main-layout";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { updateCategory, getCategoryById, type UpdateCategoryData } from "@/actions/category";
import { getAuthTokenFromClient } from "@/lib/auth";
import { generateSlug } from "@/lib/utils";
import { ArrowLeft } from "lucide-react";
import Link from "next/link";
import { toast } from "sonner";

export default function EditCategoryPage() {
  const router = useRouter();
  const params = useParams();
  const id = params.id as string;
  const [loading, setLoading] = useState(false);
  const [loadingData, setLoadingData] = useState(true);
  const [slugManuallyEdited, setSlugManuallyEdited] = useState(false);
  const [formData, setFormData] = useState<UpdateCategoryData>({
    name: "",
    slug: "",
    description: "",
    icon: "",
    color: "",
    order: 0,
    active: true,
  });

  useEffect(() => {
    loadCategory();
  }, [id]);

  const loadCategory = async () => {
    try {
      setLoadingData(true);
      const category = await getCategoryById(id);
      if (category) {
        setFormData({
          name: category.name,
          slug: category.slug,
          description: category.description || "",
          icon: category.icon || "",
          color: category.color || "",
          order: category.order || 0,
          active: category.active !== false,
        });
      }
    } catch (error) {
      console.error("Erro ao carregar categoria:", error);
    } finally {
      setLoadingData(false);
    }
  };

  // Gera slug automaticamente quando o nome mudar
  useEffect(() => {
    if (formData.name && !slugManuallyEdited) {
      setFormData((prev) => ({
        ...prev,
        slug: generateSlug(prev.name ?? ''),
      }));
    }
  }, [formData.name, slugManuallyEdited]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      setLoading(true);
      const token = getAuthTokenFromClient();
      if (!token) {
        toast.error("Token de autenticação não encontrado");
        return;
      }
      await updateCategory(id, formData, token);
      router.push("/categories");
    } catch (error: any) {
      console.error("Erro ao atualizar categoria:", error);
      toast.error(error.message || "Erro ao atualizar categoria");
    } finally {
      setLoading(false);
    }
  };

  if (loadingData) {
    return (
      <MainLayout>
        <div className="text-center py-8">Carregando...</div>
      </MainLayout>
    );
  }

  return (
    <MainLayout>
      <div className="space-y-6">
        <div className="flex items-center gap-4">
          <Link href="/categories">
            <Button variant="ghost" size="icon">
              <ArrowLeft className="h-4 w-4" />
            </Button>
          </Link>
          <div>
            <h1 className="text-3xl font-bold text-gray-900 dark:text-gray-100">Editar Categoria</h1>
            <p className="text-gray-600 dark:text-gray-400 mt-2">Atualize as informações da categoria</p>
          </div>
        </div>

        <Card>
          <CardHeader>
            <CardTitle>Informações da Categoria</CardTitle>
          </CardHeader>
          <CardContent>
            <form onSubmit={handleSubmit} className="space-y-6">
              <div className="grid gap-6 md:grid-cols-2">
                <div className="space-y-2">
                  <Label htmlFor="name">Nome *</Label>
                  <Input
                    id="name"
                    value={formData.name || ""}
                    onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                    placeholder="Ex: Front-end"
                    required
                  />
                </div>

                <div className="space-y-2">
                  <Label htmlFor="slug">Slug *</Label>
                  <Input
                    id="slug"
                    value={formData.slug || ""}
                    onChange={(e) => {
                      setFormData({ ...formData, slug: e.target.value });
                      setSlugManuallyEdited(true);
                    }}
                    placeholder="Ex: front-end"
                    required
                  />
                </div>
              </div>

              <div className="space-y-2">
                <Label htmlFor="description">Descrição</Label>
                <Textarea
                  id="description"
                  value={formData.description || ""}
                  onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                  placeholder="Descreva a categoria..."
                  rows={4}
                />
              </div>

              <div className="grid gap-6 md:grid-cols-3">
                <div className="space-y-2">
                  <Label htmlFor="icon">Ícone (emoji)</Label>
                  <Input
                    id="icon"
                    value={formData.icon || ""}
                    onChange={(e) => setFormData({ ...formData, icon: e.target.value })}
                    placeholder="Ex: 💻"
                    maxLength={2}
                  />
                </div>

                <div className="space-y-2">
                  <Label htmlFor="color">Cor (hex)</Label>
                  <div className="flex gap-2">
                    <Input
                      id="color"
                      type="color"
                      value={formData.color || "#3B82F6"}
                      onChange={(e) => setFormData({ ...formData, color: e.target.value })}
                      className="w-20 h-10"
                    />
                    <Input
                      value={formData.color || ""}
                      onChange={(e) => setFormData({ ...formData, color: e.target.value })}
                      placeholder="#3B82F6"
                      pattern="^#([A-Fa-f0-9]{6}|[A-Fa-f0-9]{3})$"
                    />
                  </div>
                </div>

                <div className="space-y-2">
                  <Label htmlFor="order">Ordem</Label>
                  <Input
                    id="order"
                    type="number"
                    value={formData.order || 0}
                    onChange={(e) => setFormData({ ...formData, order: parseInt(e.target.value) || 0 })}
                    min="0"
                  />
                </div>
              </div>

              <div className="flex items-center space-x-2">
                <input
                  type="checkbox"
                  id="active"
                  checked={formData.active !== false}
                  onChange={(e) => setFormData({ ...formData, active: e.target.checked })}
                  className="rounded border-gray-300"
                />
                <Label htmlFor="active" className="cursor-pointer">
                  Categoria ativa
                </Label>
              </div>

              <div className="flex justify-end gap-4">
                <Link href="/categories">
                  <Button type="button" variant="outline">
                    Cancelar
                  </Button>
                </Link>
                <Button type="submit" disabled={loading}>
                  {loading ? "Salvando..." : "Salvar Alterações"}
                </Button>
              </div>
            </form>
          </CardContent>
        </Card>
      </div>
    </MainLayout>
  );
}

