}

"use client";

import { useEffect, useState } from "react";
import { MainLayout } from "@/components/layout/main-layout";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { Select } from "@/components/ui/select";
import { listModules, deleteModule, type Module } from "@/actions/module";
import { listCourses } from "@/actions/course";
import { getAuthTokenFromClient } from "@/lib/auth";
import { Plus, Edit, Trash2 } from "lucide-react";
import Link from "next/link";
import { toast } from "sonner";

export default function ModulesPage() {
  const [modules, setModules] = useState<Module[]>([]);
  const [courses, setCourses] = useState<Array<{ id: string; title: string }>>([]);
  const [selectedCourse, setSelectedCourse] = useState<string>("");
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    loadCourses();
  }, []);

  useEffect(() => {
    if (selectedCourse) {
      loadModules();
    } else {
      setModules([]);
    }
  }, [selectedCourse]);

  const loadCourses = async () => {
    try {
      const { courses } = await listCourses();
      setCourses(courses.map((c) => ({ id: c.id, title: c.title })));
    } catch (error) {
      console.error("Erro ao carregar cursos:", error);
    }
  };

  const loadModules = async () => {
    try {
      setLoading(true);
      const { modules: data } = await listModules(selectedCourse);
      setModules(data);
    } catch (error) {
      console.error("Erro ao carregar módulos:", error);
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (id: string) => {
    if (!confirm("Tem certeza que deseja excluir este módulo?")) return;
    try {
      const token = getAuthTokenFromClient();
      if (!token) {
        toast.error("Token de autenticação não encontrado");
        return;
      }
      await deleteModule(id, token);
      loadModules();
    } catch (error) {
      console.error("Erro ao excluir módulo:", error);
      toast.error("Erro ao excluir módulo");
    }
  };

  return (
    <MainLayout>
      <div className="space-y-6">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-3xl font-bold text-gray-900 dark:text-gray-100">Módulos</h1>
            <p className="text-gray-600 dark:text-gray-400 mt-2">Gerencie os módulos dos cursos</p>
          </div>
          {selectedCourse && (
            <Link href={`/modules/new?courseId=${selectedCourse}`}>
              <Button>
                <Plus className="mr-2 h-4 w-4" />
                Novo Módulo
              </Button>
            </Link>
          )}
        </div>

        <Card>
          <CardHeader>
            <CardTitle>Selecione um Curso</CardTitle>
          </CardHeader>
          <CardContent>
            <Select
              value={selectedCourse}
              onChange={(e) => setSelectedCourse(e.target.value)}
            >
              <option value="">Selecione um curso</option>
              {courses.map((course) => (
                <option key={course.id} value={course.id}>
                  {course.title}
                </option>
              ))}
            </Select>
          </CardContent>
        </Card>

        {selectedCourse && (
          <Card>
            <CardHeader>
              <CardTitle>Lista de Módulos</CardTitle>
            </CardHeader>
            <CardContent>
              {loading ? (
                <div className="text-center py-8">Carregando...</div>
              ) : (
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead>Título</TableHead>
                      <TableHead>Slug</TableHead>
                      <TableHead>Ações</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {modules.length === 0 ? (
                      <TableRow>
                        <TableCell colSpan={3} className="text-center py-8 text-gray-500">
                          Nenhum módulo encontrado
                        </TableCell>
                      </TableRow>
                    ) : (
                      modules.map((module) => (
                        <TableRow key={module.id}>
                          <TableCell className="font-medium">{module.title}</TableCell>
                          <TableCell>{module.slug}</TableCell>
                          <TableCell>
                            <div className="flex gap-2">
                              <Link href={`/modules/${module.id}/edit`}>
                                <Button variant="ghost" size="icon">
                                  <Edit className="h-4 w-4" />
                                </Button>
                              </Link>
                              <Button
                                variant="ghost"
                                size="icon"
                                onClick={() => handleDelete(module.id)}
                              >
                                <Trash2 className="h-4 w-4 text-red-600" />
                              </Button>
                            </div>
                          </TableCell>
                        </TableRow>
                      ))
                    )}
                  </TableBody>
                </Table>
              )}
            </CardContent>
          </Card>
        )}
      </div>
    </MainLayout>
  );
}

"use client";

import { useState, useEffect } from "react";
import { useRouter, useParams } from "next/navigation";
import { MainLayout } from "@/components/layout/main-layout";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
  updatePlan,
  getPlanById,
  type UpdatePlanData,
} from "@/actions/plan";
import { getAuthTokenFromClient } from "@/lib/auth";
import { ArrowLeft } from "lucide-react";
import Link from "next/link";
import { toast } from "sonner";

export default function EditPlanPage() {
  const router = useRouter();
  const params = useParams();
  const id = params.id as string;
  const [loading, setLoading] = useState(false);
  const [loadingData, setLoadingData] = useState(true);
  const [formData, setFormData] = useState<UpdatePlanData>({
    slug: "",
    name: "",
    description: "",
    amountCents: 0,
    order: 0,
    active: true,
    externalId: "",
    productName: "",
  });

  useEffect(() => {
    loadPlan();
  }, [id]);

  const loadPlan = async () => {
    try {
      setLoadingData(true);
      const token = getAuthTokenFromClient();
      const plan = await getPlanById(id, token ?? undefined);
      if (plan) {
        setFormData({
          slug: plan.slug,
          name: plan.name,
          description: plan.description ?? "",
          amountCents: plan.amountCents,
          order: plan.order,
          active: plan.active,
          externalId: plan.externalId ?? "",
          productName: plan.productName ?? "",
        });
      }
    } catch (error) {
      console.error("Erro ao carregar plano:", error);
    } finally {
      setLoadingData(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      setLoading(true);
      const token = getAuthTokenFromClient();
      if (!token) {
        toast.error("Token de autenticação não encontrado");
        return;
      }
      await updatePlan(
        id,
        {
          ...formData,
          slug: formData.slug?.toUpperCase(),
          description: formData.description || null,
          externalId: formData.externalId || null,
          productName: formData.productName || null,
        },
        token
      );
      toast.success("Plano atualizado com sucesso");
      router.push("/plans");
    } catch (error: unknown) {
      console.error("Erro ao atualizar plano:", error);
      toast.error(
        error instanceof Error ? error.message : "Erro ao atualizar plano"
      );
    } finally {
      setLoading(false);
    }
  };

  if (loadingData) {
    return (
      <MainLayout>
        <div className="text-center py-8">Carregando...</div>
      </MainLayout>
    );
  }

  return (
    <MainLayout>
      <div className="space-y-6">
        <div className="flex items-center gap-4">
          <Link href="/plans">
            <Button variant="ghost" size="icon">
              <ArrowLeft className="h-4 w-4" />
            </Button>
          </Link>
          <div>
            <h1 className="text-3xl font-bold text-gray-900 dark:text-gray-100">
              Editar Plano
            </h1>
            <p className="text-gray-600 dark:text-gray-400 mt-2">
              Atualize as informações do plano
            </p>
          </div>
        </div>

        <Card>
          <CardHeader>
            <CardTitle>Informações do Plano</CardTitle>
          </CardHeader>
          <CardContent>
            <form onSubmit={handleSubmit} className="space-y-6">
              <div className="grid gap-6 md:grid-cols-2">
                <div className="space-y-2">
                  <Label htmlFor="slug">Slug *</Label>
                  <Input
                    id="slug"
                    value={formData.slug ?? ""}
                    onChange={(e) =>
                      setFormData({ ...formData, slug: e.target.value })
                    }
                    placeholder="Ex: PRO"
                    required
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="name">Nome *</Label>
                  <Input
                    id="name"
                    value={formData.name ?? ""}
                    onChange={(e) =>
                      setFormData({ ...formData, name: e.target.value })
                    }
                    placeholder="Ex: Code Legends PRO"
                    required
                  />
                </div>
              </div>

              <div className="space-y-2">
                <Label htmlFor="description">Descrição</Label>
                <Textarea
                  id="description"
                  value={formData.description ?? ""}
                  onChange={(e) =>
                    setFormData({ ...formData, description: e.target.value })
                  }
                  placeholder="Descreva o plano..."
                  rows={3}
                />
              </div>

              <div className="grid gap-6 md:grid-cols-2">
                <div className="space-y-2">
                  <Label htmlFor="amountCents">Valor (centavos) *</Label>
                  <Input
                    id="amountCents"
                    type="number"
                    min={0}
                    value={formData.amountCents ?? 0}
                    onChange={(e) =>
                      setFormData({
                        ...formData,
                        amountCents: parseInt(e.target.value, 10) || 0,
                      })
                    }
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="order">Ordem</Label>
                  <Input
                    id="order"
                    type="number"
                    min={0}
                    value={formData.order ?? 0}
                    onChange={(e) =>
                      setFormData({
                        ...formData,
                        order: parseInt(e.target.value, 10) || 0,
                      })
                    }
                  />
                </div>
              </div>

              <div className="grid gap-6 md:grid-cols-2">
                <div className="space-y-2">
                  <Label htmlFor="externalId">External ID (Abacate Pay)</Label>
                  <Input
                    id="externalId"
                    value={formData.externalId ?? ""}
                    onChange={(e) =>
                      setFormData({ ...formData, externalId: e.target.value })
                    }
                    placeholder="Ex: CODE-LEGENDS-PRO"
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="productName">Nome do produto (checkout)</Label>
                  <Input
                    id="productName"
                    value={formData.productName ?? ""}
                    onChange={(e) =>
                      setFormData({ ...formData, productName: e.target.value })
                    }
                    placeholder="Ex: Code Legends PRO - Assinatura anual"
                  />
                </div>
              </div>

              <div className="flex items-center space-x-2">
                <input
                  type="checkbox"
                  id="active"
                  checked={formData.active !== false}
                  onChange={(e) =>
                    setFormData({ ...formData, active: e.target.checked })
                  }
                  className="rounded border-gray-300"
                />
                <Label htmlFor="active" className="cursor-pointer">
                  Plano ativo
                </Label>
              </div>

              <div className="flex justify-end gap-4">
                <Link href="/plans">
                  <Button type="button" variant="outline">
                    Cancelar
                  </Button>
                </Link>
                <Button type="submit" disabled={loading}>
                  {loading ? "Salvando..." : "Salvar Alterações"}
                </Button>
              </div>
            </form>
          </CardContent>
        </Card>
      </div>
    </MainLayout>
  );
}

"use client";

import { useEffect, useState } from "react";
import { MainLayout } from "@/components/layout/main-layout";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Button } from "@/components/ui/button";
import { listSkills, type Skill } from "@/actions/skill/list-skills";
import { createSkill } from "@/actions/skill/create-skill";
import { getAuthTokenFromClient } from "@/lib/auth";
import { toast } from "sonner";
import { generateSlug } from "@/lib/utils";

export default function SkillsPage() {
  const [skills, setSkills] = useState<Skill[]>([]);
  const [loading, setLoading] = useState(false);
  const [search, setSearch] = useState("");
  const [name, setName] = useState("");
  const [slug, setSlug] = useState("");
  const [description, setDescription] = useState("");
  const [slugManuallyEdited, setSlugManuallyEdited] = useState(false);

  useEffect(() => {
    loadSkills();
  }, []);

  useEffect(() => {
    if (name && !slugManuallyEdited) {
      setSlug(generateSlug(name));
    }
  }, [name, slugManuallyEdited]);

  const loadSkills = async (searchTerm?: string) => {
    setLoading(true);
    try {
      const { skills } = await listSkills(searchTerm);
      setSkills(skills);
    } catch (error) {
      console.error("Erro ao carregar skills:", error);
      toast.error("Erro ao carregar skills");
    } finally {
      setLoading(false);
    }
  };

  const handleSearch = async (e: React.FormEvent) => {
    e.preventDefault();
    await loadSkills(search.trim() || undefined);
  };

  const handleCreate = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!name.trim()) {
      toast.error("Nome da skill é obrigatório");
      return;
    }

    const token = getAuthTokenFromClient();
    if (!token) {
      toast.error("Token de autenticação não encontrado");
      return;
    }

    try {
      setLoading(true);
      await createSkill(
        {
          name: name.trim(),
          slug: slug.trim() || generateSlug(name.trim()),
          description: description.trim() || undefined,
        },
        token
      );
      toast.success("Skill criada com sucesso");
      setName("");
      setSlug("");
      setDescription("");
      setSlugManuallyEdited(false);
      await loadSkills();
    } catch (error: any) {
      toast.error(error?.message || "Erro ao criar skill");
    } finally {
      setLoading(false);
    }
  };

  return (
    <MainLayout>
      <div className="flex flex-col gap-6">
        <Card>
          <CardHeader>
            <CardTitle>Nova skill</CardTitle>
          </CardHeader>
          <CardContent>
            <form onSubmit={handleCreate} className="space-y-4">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <Label htmlFor="name">Nome</Label>
                  <Input
                    id="name"
                    value={name}
                    onChange={(e) => setName(e.target.value)}
                  />
                </div>
                <div>
                  <Label htmlFor="slug">Slug</Label>
                  <Input
                    id="slug"
                    value={slug}
                    onChange={(e) => {
                      setSlug(e.target.value);
                      setSlugManuallyEdited(true);
                    }}
                  />
                </div>
              </div>
              <div>
                <Label htmlFor="description">Descrição</Label>
                <Input
                  id="description"
                  value={description}
                  onChange={(e) => setDescription(e.target.value)}
                />
              </div>
              <Button type="submit" disabled={loading}>
                Criar skill
              </Button>
            </form>
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle>Skills cadastradas</CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <form onSubmit={handleSearch} className="flex gap-2">
              <Input
                placeholder="Buscar skill por nome ou slug"
                value={search}
                onChange={(e) => setSearch(e.target.value)}
              />
              <Button type="submit" variant="outline">
                Buscar
              </Button>
            </form>

            {loading && <p className="text-sm text-muted-foreground">Carregando...</p>}

            {!loading && skills.length === 0 && (
              <p className="text-sm text-muted-foreground">
                Nenhuma skill cadastrada ainda.
              </p>
            )}

            {!loading && skills.length > 0 && (
              <div className="space-y-2">
                {skills.map((skill) => (
                  <div
                    key={skill.id}
                    className="flex items-center justify-between rounded-md border border-border px-3 py-2 text-sm"
                  >
                    <div>
                      <div className="font-medium">{skill.name}</div>
                      <div className="text-xs text-muted-foreground">
                        slug: {skill.slug}
                        {skill.description
                          ? ` • ${skill.description}`
                          : null}
                      </div>
                    </div>
                    {typeof skill.coursesCount === "number" && (
                      <div className="text-xs text-muted-foreground">
                        {skill.coursesCount} curso(s)
                      </div>
                    )}
                  </div>
                ))}
              </div>
            )}
          </CardContent>
        </Card>
      </div>
    </MainLayout>
  );
}

