import { toast } from "sonner";

export default function UsersPage() {
  const [users, setUsers] = useState<UserFull[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedUser, setSelectedUser] = useState<UserFull | null>(null);
  const [showDetailsModal, setShowDetailsModal] = useState(false);
  const [loadingDetails, setLoadingDetails] = useState(false);

  const [filterSearch, setFilterSearch] = useState("");
  const [filterRole, setFilterRole] = useState<string>("");
  const [filterPlan, setFilterPlan] = useState<string>("");
  const [filterOnboarding, setFilterOnboarding] = useState<string>("");

  useEffect(() => {
    loadUsers();
  }, []);

  const loadUsers = async () => {
    try {
      setLoading(true);
      const token = getAuthTokenFromClient();
      const { users: data } = await listUsers(token || undefined);
      setUsers(data);
    } catch (error) {
      console.error("Erro ao carregar usuários:", error);
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (id: string) => {
    if (!confirm("Tem certeza que deseja excluir este usuário?")) return;
    try {
      const token = getAuthTokenFromClient();
      if (!token) {
        toast.error("Token de autenticação não encontrado");
        return;
      }
      await deleteUser(id, token);
      loadUsers();
    } catch (error) {
      console.error("Erro ao excluir usuário:", error);
      toast.error("Erro ao excluir usuário");
    }
  };

  const handleViewDetails = async (id: string) => {
    try {
      setLoadingDetails(true);
      const token = getAuthTokenFromClient();
      if (!token) {
        toast.error("Token de autenticação não encontrado");
        return;
      }
      const user = await getUserById(id, token);
      if (user) {
        setSelectedUser(user);
        setShowDetailsModal(true);
      } else {
        toast.error("Usuário não encontrado");
      }
    } catch (error) {
      console.error("Erro ao carregar detalhes do usuário:", error);
      toast.error("Erro ao carregar detalhes do usuário");
    } finally {
      setLoadingDetails(false);
    }
  };

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString("pt-BR", {
      day: "2-digit",
      month: "2-digit",
      year: "numeric",
    });
  };

  const getRoleBadgeColor = (role: string) => {
    switch (role) {
      case "ADMIN":
        return "bg-purple-900/20 dark:bg-purple-500/20 text-purple-700 dark:text-purple-300";
      case "INSTRUCTOR":
        return "bg-blue-900/20 dark:bg-blue-500/20 text-blue-700 dark:text-blue-300";
      case "STUDENT":
        return "bg-emerald-900/20 dark:bg-emerald-500/20 text-emerald-700 dark:text-emerald-300";
      default:
        return "bg-gray-900/20 dark:bg-gray-500/20 text-gray-700 dark:text-gray-300";
    }
  };

  const getRoleDotColor = (role: string) => {
    switch (role) {
      case "ADMIN":
        return "bg-purple-700 dark:bg-purple-400";
      case "INSTRUCTOR":
        return "bg-blue-700 dark:bg-blue-400";
      case "STUDENT":
        return "bg-emerald-700 dark:bg-emerald-400";
      default:
        return "bg-gray-700 dark:bg-gray-400";
    }
  };

  const getRoleLabel = (role: string) => {
    switch (role) {
      case "ADMIN":
        return "Admin";
      case "INSTRUCTOR":
        return "Instrutor";
      case "STUDENT":
        return "Estudante";
      default:
        return role;
    }
  };

  const getPlanBadgeColor = (plan: string | undefined) => {
    switch (plan) {
      case "PRO":
        return "bg-purple-900/20 dark:bg-purple-500/20 text-purple-700 dark:text-purple-300";
      case "PREMIUM":
        return "bg-amber-900/20 dark:bg-amber-500/20 text-amber-700 dark:text-amber-300";
      default:
        return "bg-lime-900/20 dark:bg-lime-500/20 text-lime-700 dark:text-lime-300";
    }
  };

  const getPlanLabel = (plan: string | undefined) =>
    plan === "PREMIUM" ? "Premium" : plan === "PRO" ? "Pro" : "Free";

  const filteredUsers = useMemo(() => {
    return users.filter((user) => {
      const searchLower = filterSearch.trim().toLowerCase();
      if (searchLower) {
        const matchName = user.name.toLowerCase().includes(searchLower);
        const matchEmail = user.email.toLowerCase().includes(searchLower);
        if (!matchName && !matchEmail) return false;
      }
      if (filterRole && user.role !== filterRole) return false;
      const userPlan = user.plan ?? "FREE";
      if (filterPlan && userPlan !== filterPlan) return false;
      if (filterOnboarding === "complete" && !user.onboardingCompleted) return false;
      if (filterOnboarding === "pending" && user.onboardingCompleted) return false;
      return true;
    });
  }, [users, filterSearch, filterRole, filterPlan, filterOnboarding]);

  const hasActiveFilters =
    filterSearch.trim() !== "" || filterRole !== "" || filterPlan !== "" || filterOnboarding !== "";

  const clearFilters = () => {
    setFilterSearch("");
    setFilterRole("");
    setFilterPlan("");
    setFilterOnboarding("");
  };

  return (
    <MainLayout>
      <div className="space-y-6">
        <div className="flex items-center gap-3">
          <UsersIcon className="h-8 w-8 text-gray-900 dark:text-gray-100" />
          <div>
            <h1 className="text-3xl font-bold text-gray-900 dark:text-gray-100">Usuários</h1>
            <p className="text-gray-600 dark:text-gray-400 mt-2">
              Gerencie todos os usuários da plataforma
            </p>
          </div>
        </div>

        <Card>
          <CardHeader>
            <CardTitle>Lista de Usuários</CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            {!loading && (
              <div className="flex flex-wrap items-end gap-4 pb-4 border-b border-gray-200 dark:border-[#25252a]">
                <div className="flex-1 min-w-[200px] max-w-xs">
                  <Label htmlFor="filter-search" className="text-gray-600 dark:text-gray-400 text-xs">
                    Buscar (nome ou e-mail)
                  </Label>
                  <div className="relative mt-1">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-gray-400" />
                    <Input
                      id="filter-search"
                      type="text"
                      placeholder="Digite para filtrar..."
                      value={filterSearch}
                      onChange={(e) => setFilterSearch(e.target.value)}
                      className="pl-9"
                    />
                  </div>
                </div>
                <div className="w-[140px]">
                  <Label htmlFor="filter-role" className="text-gray-600 dark:text-gray-400 text-xs">
                    Função
                  </Label>
                  <Select
                    id="filter-role"
                    value={filterRole}
                    onChange={(e) => setFilterRole(e.target.value)}
                    className="mt-1"
                  >
                    <option value="">Todas</option>
                    <option value="ADMIN">Admin</option>
                    <option value="INSTRUCTOR">Instrutor</option>
                    <option value="STUDENT">Estudante</option>
                  </Select>
                </div>
                <div className="w-[120px]">
                  <Label htmlFor="filter-plan" className="text-gray-600 dark:text-gray-400 text-xs">
                    Plan
