  }

  return (
    <blockquote
      className={`my-3 flex gap-3 rounded-md px-3 py-2 text-sm ${style.wrapper} ${className}`}
      {...props}
    >
      {Icon && <Icon className="mt-0.5 h-4 w-4 shrink-0" aria-hidden />}
