              code={challenge.code}
              language={challenge.language ?? 'text'}
            />
          </div>
        )}
        {hasOptions && (
          <p className="text-xs text-zinc-400">
            Opções:{' '}
            {(challenge.options ?? []).map((o, i) => (
              <span key={i}>
                {i > 0 && ', '}
                <span className="text-zinc-300">{o}</span>
              </span>
            ))}
          </p>
        )}
        {challenge.explanation && (
          <p className="border-t border-zinc-700 pt-2 text-xs text-zinc-500">
            Explicação: {challenge.explanation}
          </p>
        )}
      </div>
    </div>
  )
}

function PreviewCodeBlock({ children }: ComponentProps<'pre'>) {
  const node = Array.isArray(children) ? children[0] : children

  let className: string | undefined
  let codeChildren: ReactNode = children

  if (React.isValidElement(node)) {
    const element = node as React.ReactElement<{
      className?: string
      children?: ReactNode
    }>
    className = element.props.className
    codeChildren = element.props.children
  }

  const text =
    typeof codeChildren === 'string'
      ? codeChildren
      : Array.isArray(codeChildren)
        ? codeChildren.map((c) => (typeof c === 'string' ? c : '')).join('')
        : String(codeChildren ?? '')

  const match = className?.match(/language-(\w+)/)
  const language = match ? match[1] : 'text'

  if (language === 'challenge') {
    try {
      const challenge = JSON.parse(text) as PreviewChallenge
      return <PreviewChallengeBlock challenge={challenge} />
    } catch {
      return (
        <div className="my-3 rounded-md border border-red-500/40 bg-red-950/30 px-3 py-2 text-sm text-red-400">
          Desafio inválido (JSON malformado).
        </div>
      )
    }
  }

  return (
    <div className="my-3 overflow-hidden rounded-md bg-zinc-900 text-xs leading-relaxed text-zinc-100">
      <ArticleCodeHighlighter code={text} language={language} />
    </div>
  )
}

function buildChallengeBlock(challenge: Challenge): string {
  const obj: Record<string, unknown> = {
    type: challenge.type,
    question: challenge.question,
  }
  if (challenge.code != null && challenge.code.trim() !== '') {
    obj.code = challenge.code.trim()
    obj.language = challenge.language ?? 'javascript'
  }
  if (
    Array.isArray(challenge.options) &&
    challenge.options.some((o) => o != null && String(o).trim() !== '')
  ) {
    obj.options = challenge.options.map((o) => String(o).trim()).filter(Boolean)
  }
  if (challenge.correctAnswer != null && String(challenge.correctAnswer).trim() !== '') {
    obj.correctAnswer = String(challenge.correctAnswer).trim()
  }
  if (challenge.explanation != null && String(challenge.explanation).trim() !== '') {
    obj.explanation = String(challenge.explanation).trim()
  }
  if (challenge.placeholder != null && String(challenge.placeholder).trim() !== '') {
    obj.placeholder = String(challenge.placeholder).trim()
  }
  const json = JSON.stringify(obj, null, 2)
  return '```challenge\n' + json + '\n```'
}

interface InsertChallengeModalProps {
  open: boolean
  onClose: () => void
  onInsert: (block: string) => void
}

function InsertChallengeModal({
  open,
  onClose,
  onInsert,
}: InsertChallengeModalProps) {
  const [challengeType, setChallengeType] = useState<ChallengeType>('prediction')
  const [question, setQuestion] = useState('')
  const [code, setCode] = useState('')
  const [language, setLanguage] = useState('javascript')
  const [options, setOptions] = useState<string[]>(['', ''])
  const [correctAnswer, setCorrectAnswer] = useState('')
  const [explanation, setExplanation] = useState('')

  const hasOptions =
    challengeType === 'prediction' ||
    challengeType === 'conceptual' ||
    challengeType === 'bug'
  const showCode = challengeType !== 'conceptual'

  const addOption = () => setOptions((o) => [...o, ''])
  const removeOption = (i: number) =>
    setOptions((o) => o.filter((_, idx) => idx !== i))
  const setOption = (i: number, val: string) =>
    setOptions((o) => {
      const next = [...o]
      next[i] = val
      return next
    })

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault()
    const challenge: Challenge = {
      type: challengeType,
      question: question.trim(),
      explanation: explanation.trim() || undefined,
    }
    if (showCode && code.trim()) {
      challenge.code = code.trim()
      challenge.language = language
    }
    if (hasOptions && options.some((o) => o.trim())) {
      challenge.options = options.map((o) => o.trim()).filter(Boolean)
      if (correctAnswer.trim()) challenge.correctAnswer = correctAnswer.trim()
    } else if (correctAnswer.trim()) {
      challenge.correctAnswer = correctAnswer.trim()
    }
    const block = buildChallengeBlock(challenge)
    onInsert(block)
    onClose()
    setQuestion('')
    setCode('')
    setOptions(['', ''])
    setCorrectAnswer('')
    setExplanation('')
  }

  if (!open) return null

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      <div
        className="absolute inset-0 bg-black/60"
        onClick={onClose}
        aria-hidden
      />
      <Card className="relative z-10 w-full max-w-lg max-h-[90vh] overflow-hidden flex flex-col">
        <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
          <h3 className="text-lg font-semibold">Inserir desafio</h3>
          <Button type="button" variant="ghost" size="icon" onClick={onClose}>
            <X className="h-4 w-4" />
          </Button>
        </CardHeader>
        <CardContent className="overflow-y-auto flex-1">
          <form onSubmit={handleSubmit} className="space-y-4">
            <div className="space-y-2">
              <Label>Tipo de desafio</Label>
              <Select
                value={challengeType}
                onChange={(e) =>
                  setChallengeType(e.target.value as ChallengeType)
                }
              >
                {CHALLENGE_TYPES.map((t) => (
                  <option key={t} value={t}>
                    {challengeTypeLabels[t]}
                  </option>
                ))}
              </Select>
            </div>

            <div className="space-y-2">
              <Label>Pergunta *</Label>
              <Textarea
                value={question}
                onChange={(e) => setQuestion(e.target.value)}
                rows={3}
                required
                placeholder="Ex.: O que será mostrado no console?"
              />
            </div>

            {showCode && (
              <>
                <div className="space-y-2">
                  <Label>Código (opcional)</Label>
                  <Textarea
                    value={code}
                    onChange={(e) => setCode(e.target.value)}
                    rows={4}
                    className="font-mono text-sm"
                    placeholder="const x = 1&#10;console.log(x)"
                  />
                </div>
                <div className="space-y-2">
                  <Label>Linguagem</Label>
                  <Select
                    value={language}
                    onChange={(e) => setLanguage(e.target.value)}
                  >
                    {LANGUAGES.map((lang) => (
                      <option key={lang} value={lang}>
                        {lang}
                      </option>
                    ))}
                  </Select>
                </div>
              </>
            )}

            {hasOptions && (
              <div className="space-y-2">
                <Label>Opções (mín. 2)</Label>
                {options.map((opt, i) => (
                  <div key={i} className="flex gap-2">
                    <Input
                      value={opt}
                      onChange={(e) => setOption(i, e.target.value)}
                      placeholder={`Opção ${i + 1}`}
                    />
                    {options.length > 2 && (
                      <Button
                        type="button"
                        variant="ghost"
                        size="icon"
                        onClick={() => removeOption(i)}
                      >
                        <Trash2 className="h-4 w-4" />
                      </Button>
                    )}
                  </div>
                ))}
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  onClick={addOption}
                  className="gap-1"
                >
                  <Plus className="h-4 w-4" />
                  Adicionar opção
                </Button>
              </div>
            )}

            <div className="space-y-2">
              <Label>Resposta correta</Label>
              <Input
                value={correctAnswer}
                onChange={(e) => setCorrectAnswer(e.target.value)}
                placeholder={
                  hasOptions
                    ? 'Digite ou escolha uma das opções acima'
                    : 'Resposta esperada'
                }
              />
            </div>

            <div className="space-y-2">
              <Label>Explicação (Markdown)</Label>
              <Textarea
                value={explanation}
                onChange={(e) => setExplanation(e.target.value)}
                rows={3}
                placeholder="Por que a resposta está correta..."
              />
            </div>

            <div className="flex justify-end gap-2 pt-2">
              <Button type="button" variant="outline" onClick={onClose}>
                Cancelar
              </Button>
              <Button type="submit">Inserir no artigo</Button>
            </div>
          </form>
        </CardContent>
      </Card>
    </div>
  )
}

interface ArticleBodyEditorProps {
  id: string
  value: string
  onChange: (value: string) => void
  placeholder?: string
  rows?: number
  isArticle?: boolean
  /** Se definido, Ctrl+Enter (ou Cmd+Enter) no editor dispara este callback (ex.: salvar sem fechar o modal). */
  onSaveRequested?: () => void
}

const ARTICLE_PLACEHOLDER =
  'Ex.: # Título do artigo\n\nParágrafo de abertura...\n\nUse os botões acima para inserir código, callouts e desafios.'

export function ArticleBodyEditor({
  id,
  value,
  onChange,
  placeholder,
  rows = 12,
  isArticle = false,
  onSaveRequested,
}: ArticleBodyEditorProps) {
  const effectivePlaceholder =
    placeholder ??
    (isArticle ? ARTICLE_PLACEHOLDER : 'Escreva o conteúdo em Markdown...')
  const textareaRef = useRef<HTMLTextAreaElement>(null)
  const richTextRef = useRef<RichTextEditorRef>(null)
  const [showHelp, setShowHelp] = useState(false)
  const [isExpanded, setIsExpanded] = useState(false) // Note: isExpanded might not be used anymore if we remove fullscreen mode, but we can keep the state to avoid errors
  const [insertChallengeOpen, setInsertChallengeOpen] = useState(false)
  const [previewValue, setPreviewValue] = useState(value)

  useEffect(() => {
    const t = setTimeout(() => setPreviewValue(value), 300)
    return () => clearTimeout(t)
  }, [value])

  const insertAtCursor = useCallback(
    (snippet: string) => {
      if (isArticle && richTextRef.current) {
        richTextRef.current.insertMarkdown(snippet)
        return
      }

      const textarea = textareaRef.current
      if (!textarea) {
        onChange(value + snippet)
        return
      }
      const start = textarea.selectionStart
      const end = textarea.selectionEnd
      const before = value.slice(0, start)
      const after = value.slice(end)
      const newValue = before + snippet + after
      onChange(newValue)

      // Foca e posiciona o cursor logo após o snippet inserido
      requestAnimationFrame(() => {
        textarea.focus()
        const newPos = start + snippet.length
        textarea.setSelectionRange(newPos, newPos)
      })
    },
    [value, onChange],
  )

  const hasContent = value.trim().length > 0

  const previewNode = hasContent ? (
    <div className="rounded-md border border-zinc-200 bg-white p-3 text-sm shadow-sm dark:border-zinc-800 dark:bg-zinc-950">
      <p className="mb-2 text-[10px] font-semibold uppercase tracking-[0.12em] text-zinc-500 dark:text-zinc-400">
        Pré-visualização
      </p>
      <div className="prose prose-sm max-w-none text-zinc-900 dark:prose-invert dark:text-zinc-100 prose-pre:bg-transparent prose-pre:p-0 prose-pre:border-0">
        <ReactMarkdown
          remarkPlugins={[remarkGfm]}
          components={{
            blockquote: PreviewCalloutBlockquote,
            pre: PreviewCodeBlock,
          }}
        >
          {previewValue}
        </ReactMarkdown>
      </div>
    </div>
  ) : null

  const handleInsertChallenge = useCallback(
    (block: string) => {
      insertAtCursor(block)
      setInsertChallengeOpen(false)
      requestAnimationFrame(() => {
        if (isArticle && richTextRef.current) {
          // BlockNote maintains focus generally
        } else {
          textareaRef.current?.focus()
        }
      })
    },
    [insertAtCursor, isArticle],
  )

  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
      if ((e.ctrlKey || e.metaKey) && e.key === 'Enter') {
        e.preventDefault()
        onSaveRequested?.()
      }
    },
    [onSaveRequested],
  )

  const snippetsToolbar = (
    <div className="flex flex-wrap gap-2">
      {isArticle && (
        <Button
          type="button"
          variant="default"
          size="sm"
          onClick={() => setInsertChallengeOpen(true)}
          className="gap-2"
          title="Abrir formulário para inserir desafio sem editar JSON"
        >
          <Target className="h-4 w-4" />
          Inserir desafio
        </Button>
      )}
      {SNIPPETS.map(({ label, icon: Icon, text }) => (
        <Button
          key={label}
          type="button"
          variant="outline"
          size="sm"
          onClick={() => insertAtCursor(text)}
          className="gap-2 border-dashed"
          title={`Inserir ${label}`}
        >
          <Icon className="h-4 w-4" />
          {label}
        </Button>
      ))}
    </div>
  )

  return (
    <div className="space-y-3">
      <InsertChallengeModal
        open={insertChallengeOpen}
        onClose={() => setInsertChallengeOpen(false)}
        onInsert={handleInsertChallenge}
      />
      <div className="flex items-center justify-between">
        <Label htmlFor={id}>Conteúdo do artigo (Markdown)</Label>
        {!isArticle && (
          <span className="text-xs text-muted-foreground">Suporta GFM</span>
        )}
      </div>

      {isArticle ? (
        <div className="rounded-md border border-zinc-800/60 bg-zinc-950/60 p-3 space-y-3">
          <div className="flex items-center justify-between gap-2 border-b border-zinc-800/80 pb-2">
            <div className="flex flex-col">
              <span className="text-[11px] font-semibold uppercase tracking-[0.12em] text-zinc-500">
                Editor Visual (Block Editor)
              </span>
              <span className="text-[11px] text-zinc-500">
                Digite '/' para acessar menus avançados ou arraste os blocos.
              </span>
            </div>
            {/* The maximize/minimize logic for the WYSIWYG editor could go here, but omitted for simplicity. */}
          </div>

          <div className="mt-2 flex flex-wrap items-center justify-between gap-2">
            {snippetsToolbar}
          </div>

          <div className="pt-2">
            <RichTextEditor 
              ref={richTextRef} 
              initialMarkdown={value} 
              onChange={onChange} 
              className="min-h-[400px]" 
            />
          </div>
        </div>
      ) : (
        <>
          {snippetsToolbar}

          <Textarea
            ref={textareaRef}
            id={id}
            value={value}
            onChange={(e) => onChange(e.target.value)}
            onKeyDown={handleKeyDown}
            rows={rows}
            className="font-mono text-sm leading-relaxed"
            placeholder={effectivePlaceholder}
          />
          {previewNode}
        </>
      )}

      <div className="rounded-md border border-zinc-200 bg-zinc-50 dark:border-zinc-800 dark:bg-zinc-900/50 overflow-hidden">
        <button
          type="button"
          onClick={() => setShowHelp((v) => !v)}
          className="w-full flex items-center justify-between gap-2 px-3 py-2 text-left text-xs font-medium text-zinc-700 dark:text-zinc-400 hover:bg-zinc-100 dark:hover:bg-zinc-800 transition-colors"
        >
          <span>Guia de formatação rápida</span>
          {showHelp ? (
            <ChevronUp className="h-3 w-3 shrink-0" />
          ) : (
            <ChevronDown className="h-3 w-3 shrink-0" />
          )}
        </button>

        {showHelp && (
          <div className="px-3 pb-3 pt-1 text-xs text-zinc-600 dark:text-zinc-500 space-y-3 border-t border-zinc-200 dark:border-zinc-800">
            <div className="grid gap-2">
              <p>
                <strong className="text-zinc-900 dark:text-zinc-200">
                  Bloco de código:
                </strong>
                <br />
                Use 3 crases (
                <code className="rounded bg-zinc-200 dark:bg-zinc-800 px-1 py-0.5">
                  ```
                </code>
                ), a linguagem (ex: js), e feche com 3 crases.
              </p>
              <p>
                <strong className="text-zinc-900 dark:text-zinc-200">
                  Callouts Especiais:
                </strong>
                <br />
                Inicie a linha com{' '}
                <code className="rounded bg-zinc-200 dark:bg-zinc-800 px-1 py-0.5">
                  &gt;
                </code>{' '}
                seguido da palavra-chave:
              </p>
              <ul className="list-disc list-inside space-y-1 ml-1">
                <li>
                  <code className="text-blue-600 dark:text-blue-400">Nota</code>{' '}
                  para informações azuis.
                </li>
                <li>
                  <code className="text-amber-600 dark:text-amber-400">
                    Aviso
                  </code>{' '}
                  para alertas amarelos.
                </li>
                <li>
                  <code className="text-emerald-600 dark:text-emerald-400">
                    Sucesso
                  </code>{' '}
                  para o card verde escuro.
                </li>
              </ul>
              <p>
                <strong className="text-zinc-900 dark:text-zinc-200">
                  Desafio (quiz no artigo):
                </strong>
                <br />
                Use o botão <strong>Inserir desafio</strong> para preencher
                pergunta, opções e explicação em um formulário — o JSON é
                gerado automaticamente. Ou use os snippets{' '}
                <strong>Desafio (pergunta com código)</strong> /{' '}
                <strong>Desafio (só pergunta, sem código)</strong> e edite os
                textos entre aspas no bloco, se preferir.
              </p>
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

"use client";

import { useState, useRef } from "react";
import { ModuleWithStructure } from "@/actions/course/get-course-with-structure";
import { ModuleNode } from "./module-node";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Textarea } from "@/components/ui/textarea";
import { Plus, FileJson, X, Upload } from "lucide-react";
import { createModule } from "@/actions/module/create-module";
import { createGroup } from "@/actions/group/create-group";
import {
  createLesson,
  type CreateLessonData,
} from "@/actions/lesson/create-lesson";
import { deleteModule } from "@/actions/module/delete-module";
import { getAuthTokenFromClient } from "@/lib/auth";
import { generateSlug } from "@/lib/utils";
import { toast } from "sonner";

interface CourseBuilderProps {
  courseId: string;
  courseTitle: string;
  modules: ModuleWithStructure[];
  onModulesChange: (modules: ModuleWithStructure[]) => void;
  onReloadStructure?: () => void;
}

export function CourseBuilder({
  courseId,
  courseTitle,
  modules,
  onModulesChange,
  onReloadStructure,
}: CourseBuilderProps) {
  const [expandedModules, setExpandedModules] = useState<Set<string>>(
    new Set(modules.map((m) => m.id)),
  );
  const [loading, setLoading] = useState(false);

  const [showStructureModal, setShowStructureModal] = useState(false);
  const [importJson, setImportJson] = useState("");
  const [clearBeforeImport, setClearBeforeImport] = useState(true);
  const [importLoading, setImportLoading] = useState(false);
  const [importError, setImportError] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const toggleModule = (moduleId: string) => {
    const newExpanded = new Set(expandedModules);
    if (newExpanded.has(moduleId)) {
      newExpanded.delete(moduleId);
    } else {
      newExpanded.add(moduleId);
    }
    setExpandedModules(newExpanded);
  };

  const handleAddModule = async () => {
    try {
      setLoading(true);
      const token = getAuthTokenFromClient();
      if (!token) {
        toast.error("Token de autenticação não encontrado");
        return;
      }

      const moduleNumber = modules.length + 1;
      const moduleTitle = `Módulo ${moduleNumber}`;
      const newModule = await createModule(
        courseId,
        {
          title: moduleTitle,
          slug: generateSlug(moduleTitle),
        },
        token,
      );

      const updatedModules = [
        ...modules,
        {
          id: newModule.module.id,
          title: newModule.module.title,
          slug: newModule.module.slug,
          courseId: newModule.module.courseId,
          orderIndex: modules.length,
          groups: [],
        },
      ];

      onModulesChange(updatedModules);
      setExpandedModules((prev) => new Set([...prev, newModule.module.id]));
    } catch (error: any) {
      console.error("Erro ao criar módulo:", error);
      const errorMessage = error?.message || "Erro ao criar módulo";
      toast.error(errorMessage);
    } finally {
      setLoading(false);
    }
  };

  const handleModuleUpdate = (
    moduleId: string,
    updatedModule: ModuleWithStructure,
  ) => {
    const updatedModules = modules.map((m) =>
      m.id === moduleId ? updatedModule : m,
    );
    onModulesChange(updatedModules);
  };

  const handleModuleDelete = (moduleId: string) => {
    const updatedModules = modules.filter((m) => m.id !== moduleId);
    onModulesChange(updatedModules);
    setExpandedModules((prev) => {
      const newSet = new Set(prev);
      newSet.delete(moduleId);
      return newSet;
    });
  };

  const buildExportJson = () => {
    const exportModules = modules.map((module) => ({
      title: module.title,
      slug: module.slug,
      orderIndex: module.orderIndex,
      groups: module.groups.map((group) => ({
        title: group.title,
        orderIndex: group.orderIndex,
        lessons: group.lessons.map((lesson) => ({
          title: lesson.title,
          description: lesson.description,
          type: lesson.type,
          slug: lesson.slug,
          url: lesson.url ?? undefined,
          video_url: lesson.video_url ?? undefined,
          video_duration: lesson.video_duration ?? undefined,
          isFree: lesson.isFree,
          locked: lesson.locked,
          order: lesson.order,
        })),
      })),
    }));

    return JSON.stringify(exportModules, null, 2);
  };

  const handleDownloadJson = () => {
    try {
      const json = buildExportJson();
      const safeTitle =
        courseTitle && courseTitle.trim().length > 0
          ? generateSlug(courseTitle)
          : courseId;
      const blob = new Blob([json], { type: "application/json" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `curso-${safeTitle}-${courseId}-estrutura.json`;
      document.body.appendChild(a);
      a.click();
      a.remove();
      URL.revokeObjectURL(url);
    } catch (error) {
      console.error("Erro ao baixar JSON da estrutura:", error);
      toast.error("Erro ao baixar JSON da estrutura");
    }
  };

  interface ImportLessonData {
    title: string;
    description?: string;
    type?: string;
    slug?: string;
    url?: string;
    video_url?: string;
    video_duration?: string;
    isFree?: boolean;
    locked?: boolean;
    order?: number;
  }

  interface ImportGroupData {
    title: string;
    orderIndex?: number;
    lessons: ImportLessonData[];
  }

  interface ImportModuleData {
    title: string;
    slug?: string;
    orderIndex?: number;
    groups: ImportGroupData[];
  }

  const handleImportStructure = async () => {
    if (!importJson.trim()) {
      setImportError("Por favor, insira o JSON com a estrutura do curso");
      return;
    }

    let data: ImportModuleData[];
    try {
      data = JSON.parse(importJson);
    } catch {
      setImportError("JSON inválido. Verifique a sintaxe.");
      return;
    }

    if (!Array.isArray(data) || data.length === 0) {
      setImportError("O JSON deve ser um array de módulos com grupos e aulas");
      return;
    }

    const token = getAuthTokenFromClient();
    if (!token) {
      setImportError("Token de autenticação não encontrado");
      return;
    }

    try {
      setImportLoading(true);
      setImportError(null);

      if (clearBeforeImport && modules.length > 0) {
        for (const module of modules) {
          try {
            await deleteModule(module.id, token);
          } catch (error: any) {
            console.error("Erro ao excluir módulo:", error);
            // continua para tentar importar o restante
          }
        }
      }

      for (let moduleIndex = 0; moduleIndex < data.length; moduleIndex++) {
        const module = data[moduleIndex];
        if (!module?.title) continue;

        const moduleSlug = module.slug || generateSlug(module.title);
        const createdModule = await createModule(
          courseId,
          {
            title: module.title,
            slug: moduleSlug,
          },
          token,
        );

        const moduleId = createdModule.module.id;
        const groups = module.groups || [];

        for (let groupIndex = 0; groupIndex < groups.length; groupIndex++) {
          const group = groups[groupIndex];
          if (!group?.title) continue;

          const createdGroup = await createGroup(
            moduleId,
            { title: group.title },
            token,
          );

          const groupId = createdGroup.group.id;
          const lessons = group.lessons || [];

          for (let lessonIndex = 0; lessonIndex < lessons.length; lessonIndex++) {
            const lesson = lessons[lessonIndex];
            if (!lesson?.title) continue;

            const slug = lesson.slug || generateSlug(lesson.title);
            const rawDescription = (lesson.description ?? "").toString();
            const description = rawDescription;
            const rawType = (lesson.type ?? "video").toString().toLowerCase();
            const allowedTypes = [
              "video",
              "article",
              "text",
              "quiz",
              "multi_quiz",
              "project",
            ];
            const normalizedType = allowedTypes.includes(rawType)
              ? rawType
              : "video";
            const lessonData: CreateLessonData = {
              title: lesson.title,
              description,
              type: normalizedType,
              slug,
              url: lesson.url,
              video_url: lesson.video_url,
              video_duration: lesson.video_duration,
              isFree: lesson.isFree ?? false,
              locked: lesson.locked ?? false,
              order: lesson.order ?? lessonIndex + 1,
            };

            await createLesson(groupId, lessonData, token);
          }
        }
      }

      toast.success("Estrutura do curso importada com sucesso!");
      setShowStructureModal(false);
      setImportJson("");
      setImportError(null);
      if (onReloadStructure) {
        onReloadStructure();
      }
    } catch (error: any) {
      console.error("Erro ao importar estrutura do curso:", error);
      setImportError(
        error?.message || "Erro ao importar estrutura do curso. Tente novamente.",
      );
    } finally {
      setImportLoading(false);
    }
  };

  const exportJson = buildExportJson();

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between gap-3">
        <h3 className="text-lg font-semibold text-gray-900 dark:text-gray-100">
          Estrutura do Curso
        </h3>
        <div className="flex items-center gap-2">
          <Button
            variant="outline"
            size="sm"
            onClick={() => setShowStructureModal(true)}
          >
            <FileJson className="mr-2 h-4 w-4" />
            Estrutura JSON
          </Button>
          <Button onClick={handleAddModule} disabled={loading} size="sm">
            <Plus className="mr-2 h-4 w-4" />
            Adicionar Módulo
          </Button>
        </div>
      </div>

      <div className="space-y-2">
        {modules.length === 0 ? (
          <div className="text-center py-8 text-gray-500 dark:text-gray-400">
            Nenhum módulo cadastrado. Clique em "Adicionar Módulo" para começar.
          </div>
        ) : (
          modules
            .filter((module) => module.id) // Filtrar módulos sem ID válido
            .map((module) => (
              <ModuleNode
                key={module.id}
                module={module}
                isExpanded={expandedModules.has(module.id)}
                onToggle={() => toggleModule(module.id)}
                onUpdate={(updated) => handleModuleUpdate(module.id, updated)}
                onDelete={() => handleModuleDelete(module.id)}
                onReloadStructure={onReloadStructure}
              />
            ))
        )}
      </div>

      {showStructureModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50">
          <Card className="w-full max-w-4xl max-h-[90vh] overflow-y-auto">
            <CardHeader>
              <div className="flex items-center justify-between">
                <CardTitle className="flex items-center gap-2">
                  <FileJson className="h-5 w-5" />
                  Exportar / Importar Estrutura do Curso
                </CardTitle>
                <Button
                  variant="ghost"
                  size="icon"
                  onClick={() => {
                    setShowStructureModal(false);
                    setImportError(null);
                  }}
                >
                  <X className="h-4 w-4" />
                </Button>
              </div>
            </CardHeader>
            <CardContent>
              <div className="space-y-6">
                <div className="space-y-2">
                  <p className="text-sm text-gray-600 dark:text-gray-400">
                    Use esta ferramenta para copiar a estrutura completa de
                    módulos, grupos e aulas de um curso, ou importar a estrutura
                    em outro curso.
                  </p>
                  <label className="text-sm font-medium text-gray-900 dark:text-gray-100">
                    Estrutura atual (somente leitura)
                  </label>
                  <Textarea
                    value={exportJson}
                    readOnly
                    rows={12}
                    className="font-mono text-xs"
                  />
                  <div className="flex gap-2 justify-end">
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => {
                        navigator.clipboard.writeText(exportJson);
                        toast.success("JSON copiado para a área de transferência");
                      }}
                    >
                      Copiar JSON
                    </Button>
                    <Button variant="outline" size="sm" onClick={handleDownloadJson}>
                      Baixar .json
                    </Button>
                  </div>
                </div>

                <div className="border-t border-gray-200 dark:border-gray-800 pt-4 space-y-2">
                  <div className="flex items-center justify-between gap-2">
                    <label className="text-sm font-medium text-gray-900 dark:text-gray-100">
                      Importar nova estrutura (substitui ou adiciona módulos)
                    </label>
                    <input
                      ref={fileInputRef}
                      type="file"
                      accept=".json,application/json"
                      className="hidden"
                      onChange={(e) => {
                        const file = e.target.files?.[0];
                        if (!file) return;
                        const reader = new FileReader();
                        reader.onload = () => {
                          const text = reader.result;
                          if (typeof text === "string") {
                            setImportJson(text);
                            setImportError(null);
                            toast.success("Arquivo carregado. Revise e clique em Importar Estrutura.");
                          }
                        };
                        reader.onerror = () => {
                          toast.error("Erro ao ler o arquivo");
                        };
                        reader.readAsText(file, "utf-8");
                        e.target.value = "";
                      }}
                    />
                    <Button
                      type="button"
                      variant="outline"
                      size="sm"
                      onClick={() => fileInputRef.current?.click()}
                    >
                      <Upload className="mr-2 h-4 w-4" />
                      Selecionar arquivo .json
                    </Button>
                  </div>
                  <Textarea
                    placeholder='[\n  {\n    "title": "Módulo 1",\n    "groups": [\n      {\n        "title": "Grupo 1",\n        "lessons": [\n          {\n            "title": "Introdução",\n            "description": "Descrição da aula",\n            "type": "video",\n            "slug": "introducao",\n            "isFree": false,\n            "locked": false,\n            "order": 1\n          }\n        ]\n      }\n    ]\n  }\n]'
                    value={importJson}
                    onChange={(e) => setImportJson(e.target.value)}
                    rows={12}
                    className="font-mono text-xs"
                  />
                  <div className="flex items-center gap-2">
                    <input
                      id="clearBeforeImport"
                      type="checkbox"
                      className="h-4 w-4 rounded border-gray-300 text-blue-600 focus:ring-blue-500"
                      checked={clearBeforeImport}
                      onChange={(e) => setClearBeforeImport(e.target.checked)}
                    />
                    <label
                      htmlFor="clearBeforeImport"
                      className="text-sm text-gray-700 dark:text-gray-300"
                    >
                      Apagar estrutura atual antes de importar
                    </label>
                  </div>

                  {importError && (
                    <div className="mt-2 rounded border border-red-200 bg-red-50 px-3 py-2 text-sm text-red-700 dark:border-red-800 dark:bg-red-900/20 dark:text-red-300 whitespace-pre-line">
                      {importError}
                    </div>
                  )}

                  <div className="flex justify-end gap-2 pt-2">
                    <Button
                      variant="outline"
                      onClick={() => {
                        setShowStructureModal(false);
                        setImportError(null);
                      }}
                      disabled={importLoading}
                    >
                      Cancelar
                    </Button>
                    <Button onClick={handleImportStructure} disabled={importLoading}>
                      {importLoading ? "Importando..." : "Importar Estrutura"}
                    </Button>
                  </div>
                </div>
              </div>
            </CardContent>
          </Card>
        </div>
      )}
    </div>
  );
}

"use client";

import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { createLesson, type CreateLessonData } from "@/actions/lesson/create-lesson";
import { getAuthTokenFromClient } from "@/lib/auth";
import { X, FileJson } from "lucide-react";

interface ImportLessonsModalProps {
    groupId: number;
    isOpen: boolean;
    onClose: () => void;
    onImportComplete: () => void;
}

interface LessonImportData {
    title: string;
    description: string;
    type?: string;
    slug?: string;
    url?: string;
    video_url?: string;
    video_duration?: string;
    isFree?: boolean;
    locked?: boolean;
    order?: number;
}

export function ImportLessonsModal({
    groupId,
    isOpen,
    onClose,
    onImportComplete,
}: ImportLessonsModalProps) {
    const [jsonInput, setJsonInput] = useState("");
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [success, setSuccess] = useState<number>(0);

    const handleImport = async () => {
        if (!jsonInput.trim()) {
            setError("Por favor, insira o JSON com as aulas");
            return;
        }

        try {
            setLoading(true);
            setError(null);
            setSuccess(0);

            const token = getAuthTokenFromClient();
            if (!token) {
                setError("Token de autenticação não encontrado");
                return;
            }

            // Parse do JSON
            let lessonsData: LessonImportData[];
            try {
                lessonsData = JSON.parse(jsonInput);
            } catch (parseError) {
                setError("JSON inválido. Verifique a sintaxe.");
                return;
            }

            if (!Array.isArray(lessonsData)) {
                setError("O JSON deve ser um array de aulas");
                return;
            }

            if (lessonsData.length === 0) {
                setError("O array está vazio");
                return;
            }

            const errors: string[] = [];
            let successCount = 0;

            // Criar cada aula
            for (let i = 0; i < lessonsData.length; i++) {
                const lesson = lessonsData[i];
                try {
                    // Validar campos obrigatórios
                    if (!lesson.title || !lesson.description) {
                        errors.push(`Aula ${i + 1}: Título e descrição são obrigatórios`);
                        continue;
                    }

                    // Gerar slug se não fornecido
                    const slug =
                        lesson.slug ||
                        lesson.title
                            .toLowerCase()
                            .normalize("NFD")
                            .replace(/[\u0300-\u036f]/g, "")
                            .replace(/[^a-z0-9]+/g, "-")
                            .replace(/^-+|-+$/g, "");

                    const lessonData: CreateLessonData = {
                        title: lesson.title,
                        description: lesson.description,
                        type: lesson.type || "video",
                        slug: slug,
                        url: lesson.url,
                        video_url: lesson.video_url,
                        video_duration: lesson.video_duration,
                        isFree: lesson.isFree ?? false,
                        locked: lesson.locked ?? false,
                        order: lesson.order ?? i + 1,
                    };

                    await createLesson(groupId, lessonData, token);
                    successCount++;
                } catch (error: any) {
                    errors.push(
                        `Aula ${i + 1} (${lesson.title || "sem título"}): ${error.message || "Erro desconhecido"}`
                    );
                }
            }

            setSuccess(successCount);
            if (errors.length > 0) {
                setError(
                    `${errors.length} erro(s) ao importar:\n${errors.slice(0, 5).join("\n")}${errors.length > 5 ? `\n... e mais ${errors.length - 5} erro(s)` : ""
                    }`
                );
            } else {
                setError(null);
            }

            if (successCount > 0) {
                onImportComplete();
                setTimeout(() => {
                    handleClose();
                }, 2000);
            }
        } catch (error: any) {
            setError(error.message || "Erro ao importar aulas");
        } finally {
            setLoading(false);
        }
    };

    const handleClose = () => {
        setJsonInput("");
        setError(null);
        setSuccess(0);
        onClose();
    };

    const exampleJson = `[
  {
    "title": "Introdução ao React",
    "description": "Aprenda os conceitos básicos do React",
    "type": "video",
    "slug": "introducao-ao-react",
    "video_url": "https://example.com/video1.mp4",
    "video_duration": "00:15:30",
    "isFree": false,
    "locked": false,
    "order": 1
  },
  {
    "title": "Componentes React",
    "description": "Entenda como criar componentes",
    "type": "video",
    "slug": "componentes-react",
    "video_url": "https://example.com/video2.mp4",
    "video_duration": "00:20:00",
    "isFree": false,
    "locked": false,
    "order": 2
  }
]`;

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
            <Card className="w-full max-w-3xl max-h-[90vh] overflow-y-auto">
                <CardHeader>
                    <div className="flex items-center justify-between">
                        <CardTitle className="flex items-center gap-2">
                            <FileJson className="h-5 w-5" />
                            Importar Aulas via JSON
                        </CardTitle>
                        <Button variant="ghost" size="icon" onClick={handleClose}>
                            <X className="h-4 w-4" />
                        </Button>
                    </div>
                </CardHeader>
                <CardContent>
                    <div className="space-y-4">
                        <div className="space-y-2">
                            <Label htmlFor="jsonInput">JSON das Aulas</Label>
                            <Textarea
                                id="jsonInput"
                                value={jsonInput}
                                onChange={(e) => setJsonInput(e.target.value)}
                                placeholder={exampleJson}
                                rows={15}
                                className="font-mono text-sm"
                            />
                            <p className="text-sm text-gray-500 dark:text-gray-400">
                                Cole aqui o JSON com um array de aulas. Campos obrigatórios: title, description.
                                Slug será gerado automaticamente se não fornecido.
                            </p>
                        </div>

                        {error && (
                            <div className="p-3 bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded text-red-700 dark:text-red-300 text-sm whitespace-pre-line">
                                {error}
                            </div>
                        )}

                        {success > 0 && !error && (
                            <div className="p-3 bg-emerald-50 dark:bg-emerald-900/20 border border-emerald-200 dark:border-emerald-800 rounded text-emerald-700 dark:text-emerald-300 text-sm">
                                {success} aula(s) importada(s) com sucesso!
                            </div>
                        )}

                        <div className="flex justify-end gap-4 pt-4">
                            <Button variant="outline" onClick={handleClose} disabled={loading}>
                                Cancelar
                            </Button>
                            <Button onClick={handleImport} disabled={loading}>
                                {loading ? "Importando..." : "Importar Aulas"}
                            </Button>
                        </div>
                    </div>
                </CardContent>
            </Card>
        </div>
    );
}

"use client";

import { useState } from "react";
import { ModuleWithStructure, GroupWithStructure } from "@/actions/course/get-course-with-structure";
import { GroupNode, type GroupNodeProps } from "./group-node";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { ChevronDown, ChevronRight, Edit, Trash2, Plus, Save, X } from "lucide-react";
import { updateModule } from "@/actions/module/update-module";
import { deleteModule } from "@/actions/module/delete-module";
import { createGroup } from "@/actions/group/create-group";
import { getAuthTokenFromClient } from "@/lib/auth";
import { toast } from "sonner";

interface ModuleNodeProps {
    module: ModuleWithStructure;
    isExpanded: boolean;
    onToggle: () => void;
    onUpdate: (module: ModuleWithStructure) => void;
    onDelete: () => void;
    onReloadStructure?: () => void;
}

export function ModuleNode({
    module,
    isExpanded,
    onToggle,
    onUpdate,
    onDelete,
    onReloadStructure,
}: ModuleNodeProps) {
    const [isEditing, setIsEditing] = useState(false);
    const [title, setTitle] = useState(module.title);
    const [loading, setLoading] = useState(false);
    const [expandedGroups, setExpandedGroups] = useState<Set<number>>(
        new Set(module.groups.map((g) => g.id))
    );

    const handleSave = async () => {
        try {
            setLoading(true);
            const token = getAuthTokenFromClient();
            if (!token) {
                toast.error("Token de autenticação não encontrado");
                return;
            }

            await updateModule(module.id, { title }, token);
            onUpdate({ ...module, title });
            setIsEditing(false);
        } catch (error) {
            console.error("Erro ao atualizar módulo:", error);
            toast.error("Erro ao atualizar módulo");
        } finally {
            setLoading(false);
        }
    };

    const handleDelete = async () => {
        if (!confirm(`Tem certeza que deseja excluir o módulo "${module.title}"?`)) {
            return;
        }

        try {
            setLoading(true);
            const token = getAuthTokenFromClient();
            if (!token) {
                toast.error("Token de autenticação não encontrado");
                return;
            }

            await deleteModule(module.id, token);
            onDelete();
        } catch (error) {
            console.error("Erro ao excluir módulo:", error);
            toast.error("Erro ao excluir módulo");
        } finally {
            setLoading(false);
        }
    };

    const handleAddGroup = async () => {
        try {
            setLoading(true);
            const token = getAuthTokenFromClient();
            if (!token) {
                toast.error("Token de autenticação não encontrado");
                return;
            }

            const groupNumber = module.groups.length + 1;
            const newGroup = await createGroup(
                module.id,
                { title: `Submódulo ${groupNumber}` },
                token
            );

            const updatedGroups: GroupWithStructure[] = [
                ...module.groups,
                {
                    id: newGroup.group.id,
                    title: newGroup.group.title,
                    moduleId: newGroup.group.moduleId,
                    orderIndex: module.groups.length,
                    lessons: [],
                },
            ];

            onUpdate({ ...module, groups: updatedGroups });
            setExpandedGroups((prev) => new Set([...prev, newGroup.group.id]));
        } catch (error) {
            console.error("Erro ao criar submódulo:", error);
            toast.error("Erro ao criar submódulo");
        } finally {
            setLoading(false);
        }
    };

    const toggleGroup = (groupId: number) => {
        const newExpanded = new Set(expandedGroups);
        if (newExpanded.has(groupId)) {
            newExpanded.delete(groupId);
        } else {
            newExpanded.add(groupId);
        }
        setExpandedGroups(newExpanded);
    };

    const handleGroupUpdate = (groupId: number, updatedGroup: GroupWithStructure) => {
        const updatedGroups = module.groups.map((g) =>
            g.id === groupId ? updatedGroup : g
        );
        onUpdate({ ...module, groups: updatedGroups });
    };

    const handleGroupDelete = (groupId: number) => {
        const updatedGroups = module.groups.filter((g) => g.id !== groupId);
        onUpdate({ ...module, groups: updatedGroups });
        setExpandedGroups((prev) => {
            const newSet = new Set(prev);
            newSet.delete(groupId);
            return newSet;
        });
    };

    return (
        <div className="border border-gray-200 dark:border-gray-700 rounded-lg">
            <div className="flex items-center gap-2 p-3 bg-gray-50 dark:bg-gray-800">
                <button
                    onClick={onToggle}
                    className="p-1 hover:bg-gray-200 dark:hover:bg-gray-700 rounded"
                >
                    {isExpanded ? (
                        <ChevronDown className="h-4 w-4" />
                    ) : (
                        <ChevronRight className="h-4 w-4" />
                    )}
                </button>

                {isEditing ? (
                    <div className="flex-1 flex items-center gap-2">
                        <Input
                            value={title}
                            onChange={(e) => setTitle(e.target.value)}
                            className="flex-1"
                            autoFocus
                        />
                        <Button size="sm" onClick={handleSave} disabled={loading}>
                            <Save className="h-4 w-4" />
                        </Button>
                        <Button
                            size="sm"
                            variant="ghost"
                            onClick={() => {
                                setIsEditing(false);
                                setTitle(module.title);
                            }}
                        >
                            <X className="h-4 w-4" />
                        </Button>
                    </div>
                ) : (
                    <>
                        <span className="flex-1 font-medium text-gray-900 dark:text-gray-100">
                            {module.title}
                        </span>
                        <Button
                            size="sm"
                            variant="ghost"
                            onClick={() => setIsEditing(true)}
                            disabled={loading}
                        >
                            <Edit className="h-4 w-4" />
                        </Button>
                        <Button
                            size="sm"
                            variant="ghost"
                            onClick={handleAddGroup}
                            disabled={loading}
                        >
                            <Plus className="h-4 w-4" />
                        </Button>
                        <Button
                            size="sm"
                            variant="ghost"
                            onClick={handleDelete}
                            disabled={loading}
                        >
                            <Trash2 className="h-4 w-4 text-red-600" />
                        </Button>
                    </>
                )}
            </div>

            {isExpanded && (
                <div className="p-3 space-y-2">
                    {module.groups.length === 0 ? (
                        <div className="text-sm text-gray-500 dark:text-gray-400 pl-6">
                            Nenhum submódulo. Clique no botão + para adicionar.
                        </div>
                    ) : (
                        module.groups.map((group) => (
                            <GroupNode
                                key={group.id}
                                group={group}
                                isExpanded={expandedGroups.has(group.id)}
                                onToggle={() => toggleGroup(group.id)}
                                onUpdate={(updated) => handleGroupUpdate(group.id, updated)}
                                onDelete={() => handleGroupDelete(group.id)}
                                onReloadStructure={onReloadStructure}
                            />
                        ))
                    )}
                </div>
            )}
        </div>
    );
}

'use client';
import { useCreateBlockNote } from "@blocknote/react";
import { BlockNoteView } from "@blocknote/mantine";
import "@blocknote/mantine/style.css";
import { useCallback, useEffect, useState, forwardRef, useImperativeHandle } from "react";

export interface RichTextEditorRef {
  insertMarkdown: (markdown: string) => Promise<void>;
}

interface RichTextEditorProps {
  initialMarkdown: string;
  onChange: (markdown: string) => void;
  placeholder?: string;
  className?: string;
}

export const RichTextEditor = forwardRef<RichTextEditorRef, RichTextEditorProps>(
  ({ initialMarkdown, onChange, placeholder, className }, ref) => {
    const [initialContentReady, setInitialContentReady] = useState(false);

    // Cria o editor.
    const editor = useCreateBlockNote();

    useImperativeHandle(ref, () => ({
      insertMarkdown: async (markdown: string) => {
        try {
          const blocks = await editor.tryParseMarkdownToBlocks(markdown);
          editor.insertBlocks(blocks, editor.getTextCursorPosition().block, "after");
        } catch (e) {
          console.error("Failed to insert markdown", e);
        }
      }
    }));

    // Carrega o markdown inicial apenas uma vez
    useEffect(() => {
      async function loadInitialMarkdown() {
        if (initialMarkdown) {
          try {
            const blocks = await editor.tryParseMarkdownToBlocks(initialMarkdown);
            editor.replaceBlocks(editor.document, blocks);
          } catch (e) {
            console.error("Failed to parse initial markdown", e);
          }
        }
        setInitialContentReady(true);
      }
      loadInitialMarkdown();
      // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []); // Executa apenas na montagem

    const handleChange = useCallback(async () => {
      if (!initialContentReady) return;
      const markdown = await editor.blocksToMarkdownLossy(editor.document);
      onChange(markdown);
    }, [editor, initialContentReady, onChange]);

    if (!initialContentReady) {
      return (
        <div className={`p-4 text-sm text-zinc-500 animate-pulse ${className || ''}`}>
          Carregando editor visual...
        </div>
      );
    }

    return (
      <div className={className}>
        <BlockNoteView
          editor={editor}
          onChange={handleChange}
          theme={"dark"}
        />
      </div>
    );
  }
);

RichTextEditor.displayName = "RichTextEditor";

